   "wifi_ap_mode": {
    "v": "addon",
    "note": "On the ESP32 add-on only."
   },
   "nrf24_scan": {
    "v": "addon",
    "note": "Needs an nRF24L01+ module wired to the GPIO header. Apps exist in the community app packs."
   },
   "mousejack": {
    "v": "addon",
    "note": "MouseJacker app plus an nRF24L01+ module on GPIO. Only works against unpatched 2.4 GHz keyboard/mouse dongles, a shrinking target set."
   },
   "sdr_rx": {
    "v": "no",
    "note": "Not an SDR. The CC1101 is a fixed-function narrowband transceiver - you tune it to a frequency and modulation, you do not get IQ samples."
   },
   "sdr_tx": {
    "v": "no",
    "note": "Same - no arbitrary waveform generation."
   },
   "subghz_tx": {
    "v": "partial",
    "note": "REGION-LOCKED. The firmware has a 'region' service; the provisioning app sets your region on first update and TX is limited to that region's civil allow-list - e.g. EU gets 433.05-434.79 and 868.15-868.55 MHz, US/Americas get 304.10-321.95 and 915-928 MHz. Try anything else and it refuses with 'transmission on this frequency is restricted in your region'. RX stays unrestricted."
   },
   "subghz_rolling_code": {
    "v": "partial",
    "note": "It can RECORD a rolling-code transmission and tell you the protocol (KeeLoq, Security+ 2.0, Somfy, etc.), but replaying a captured code does not work by design - the receiver has already moved past it. Stock firmware deliberately ships no rolling-code bypass."
   },
   "subghz_bruteforce": {
    "v": "no",
    "note": "No brute-force app in stock firmware. Community apps add it, and it only ever helps against short static codes such as 8-12 bit DIP-switch remotes."
   },
   "mifare_classic_attacks": {
    "v": "partial",
    "note": "Dictionary attack against known/default keys runs on device. The mfkey32 READER attack also runs on device (via the mfkey app from the catalog): you emulate the card at a real reader, collect nonces, and crack Crypto-1 - minutes on the Flipper's CPU. What you cannot do on stock is a card-only attack - no nested/hardnested is built in."
   },
   "nfc_type4_ndef": {
    "v": "partial",
    "note": "Official firmware has an ISO14443-4A listener and an NDEF parser plugin, so it reads NDEF fine. It has NO Type4Tag or Ntag4xx protocol module - those exist only in the community forks - so it cannot present itself as a writable NDEF Type 4 tag."
   },
   "emv_read": {
    "v": "no",
    "note": "Official firmware has only a small helper table (nfc_emv_parser.c) that resolves EMV application IDs and currency codes for other parsers. There is NO EMV poller in the official tree - the protocol module does not exist. You cannot 'read a bank card' on stock firmware."
   },
   "hf_1356_emulate": {
    "v": "partial",
    "note": "Emulation exists for ISO14443-3A, ISO14443-4A, ISO15693-3, MIFARE Ultralight, MIFARE Classic, SLIX and FeliCa. It does NOT exist for ISO14443-3B, ISO14443-4B, DESFire or ST25TB - those entries are NULL in nfc_listener_defs.c."
   },
   "ble_scan": {
    "v": "no",
    "note": "No BLE scanner app in stock firmware."
   },
   "ble_spam_apple": {
    "v": "no",
    "note": "Not in official firmware. Community forks only."
   },
   "ble_spam_android": {
    "v": "no",
    "note": "Not in official firmware."
   },
   "ble_spam_samsung": {
    "v": "no",
    "note": "Not in official firmware."
   },
   "ble_spam_swift_pair": {
    "v": "no",
    "note": "Not in official firmware."
   },
   "findmy_track": {
    "v": "no",
    "note": "The FindMy Flipper app is not part of official firmware."
   },
   "magspoof": {
    "v": "addon",
    "note": "Needs external magspoof coil hardware on GPIO plus a community app; not a stock feature."
   },
   "usb_mass_storage": {
    "v": "partial",
    "note": "Available as a catalog app rather than built in."
   },
